package iotest

import (
	"bytes"
	"testing"
)

func TestTruncateWriter(t *testing.T) {
	w := io.NopCloser(bytes.NewBuffer([]byte("abcdefgh")))
	tw := TruncateWriter(w, 5)
	if _, err := tw.Write([]byte("abcdefgh")); err != nil {
		t.Fatal(err)
	}
	if _, err := tw.Write([]byte("abcdefgh")); err == nil {
		t.Error("expected error")
	}
	if _, err := tw.Write([]byte("abcdefgh")); err != nil {
		if !bytes.Contains(err.Error(), "Truncated") {
			t.Error(err)
		}
	}
}

